from setta.tasks.fns import InteractiveTaskDefinition
import base64
from io import BytesIO
from PIL import Image, ImageFilter

def decode_img(base64_img):
    image_data = base64.b64decode(base64_img)
    return Image.open(BytesIO(image_data))

def encode_img(img):
    buffered = BytesIO()
    img.save(buffered, format="png")
    return base64.b64encode(buffered.getvalue()).decode('utf-8')    



def fn(message):
    data = message.content
    img = data["mid_peach"]["strokes"]
    img = decode_img(img)
    img = img.filter(ImageFilter.GaussianBlur(radius=5))
    img = encode_img(img)
    return {"content": [{"value": img, "type": "img", "displayName": "blurredImg"}]}


interactive_example = InteractiveTaskDefinition(fn=fn)
